export interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string; // Base64 string
  timestamp: number;
  isError?: boolean;
}

export interface ChatState {
  messages: Message[];
  isLoading: boolean;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Message } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_NAME = 'gemini-3-flash-preview';

/**
 * Sends a message to Gemini, optionally including an image.
 */
export const sendMessageToGemini = async (
  prompt: string,
  imageBase64?: string,
  history?: Message[]
): Promise<string> => {
  try {
    // Construct the prompt parts
    const parts: any[] = [];

    if (imageBase64) {
      // Clean base64 string if it contains metadata prefix
      const cleanBase64 = imageBase64.split(',')[1] || imageBase64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg', // Assuming JPEG from camera/upload usually
          data: cleanBase64,
        },
      });
    }

    if (prompt) {
      parts.push({
        text: prompt,
      });
    }

    // Note: For a "simple" stateless app experience, we aren't maintaining
    // full multi-turn chat history context in the API call for simplicity and token efficiency,
    // but in a production app, we would map `history` to Content objects.
    // We strictly use generateContent here.

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: parts,
      },
      config: {
        systemInstruction: "You are a helpful, concise mobile assistant. Keep answers short and easy to read on a phone screen.",
      }
    });

    return response.text || "I couldn't generate a text response.";

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Failed to connect to Gemini.");
  }
};

